// Loads environment variables from .env (if present) for local dev convenience.
// This avoids needing to manually export vars in the shell.
// Safe: does NOT print secrets.

import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import dotenv from 'dotenv';

function loadIfExists(p) {
  try {
    if (fs.existsSync(p)) {
      dotenv.config({ path: p });
      return true;
    }
  } catch {}
  return false;
}

// Priority:
// 1) .env in current working directory (where user runs scripts)
// 2) .env next to this file (scripts/.env)
loadIfExists(path.resolve(process.cwd(), '.env'));
loadIfExists(path.resolve(path.dirname(fileURLToPath(import.meta.url)), '.env'));

import './_env.js';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { JsonRpcProvider, Wallet, Contract, parseEther } from 'ethers';
import { defaultSecretsDir } from './_paths.js';

export const LINK = {
  base: '0x88Fb150BDc53A65fe94Dea0c9BA0a6dAf8C6e196',
  'base-sepolia': '0xE4aB69C077896252FAFBD49EFD26B5D171A32410'
};

export const ERC20_ABI = [
  'function balanceOf(address) view returns (uint256)',
  'function decimals() view returns (uint8)',
  'function symbol() view returns (string)',
  'function transfer(address,uint256) returns (bool)'
];

// ---- BountyEscrow contract addresses (canonical, from Blockchain docs) ----

export const ESCROW = {
  'base': process.env.BOUNTY_ESCROW_ADDRESS_BASE || '0x0a6290EfA369Bbd4a9886ab9f98d7fAd7b0dc746',
  'base-sepolia': process.env.BOUNTY_ESCROW_ADDRESS_BASE_SEPOLIA || '0x0520b15Ee61C4E2A1B00bA260d8B1FBD015D2780',
};

// ---- BountyEscrow ABI (subset needed by scripts) ----

export const BOUNTY_ESCROW_ABI = [
  // Events
  'event BountyCreated(uint256 indexed bountyId, address indexed creator, string evaluationCid, uint64 classId, uint8 threshold, uint256 payoutWei, uint64 submissionDeadline)',
  'event SubmissionPrepared(uint256 indexed bountyId, uint256 indexed submissionId, address indexed hunter, address evalWallet, string evaluationCid, uint256 linkMaxBudget)',
  'event WorkSubmitted(uint256 indexed bountyId, uint256 indexed submissionId, bytes32 verdiktaAggId)',
  'event SubmissionFinalized(uint256 indexed bountyId, uint256 indexed submissionId, uint8 status, uint256 acceptance)',
  'event PayoutSent(uint256 indexed bountyId, address indexed winner, uint256 amount)',
  // Write
  'function createBounty(string evaluationCid, uint64 requestedClass, uint8 threshold, uint64 submissionDeadline) payable returns (uint256)',
  'function prepareSubmission(uint256 bountyId, string evaluationCid, string hunterCid, string addendum, uint256 alpha, uint256 maxOracleFee, uint256 estimatedBaseCost, uint256 maxFeeBasedScaling) returns (uint256 submissionId, address evalWallet, uint256 linkMaxBudget)',
  'function startPreparedSubmission(uint256 bountyId, uint256 submissionId)',
  'function finalizeSubmission(uint256 bountyId, uint256 submissionId)',
  'function closeExpiredBounty(uint256 bountyId)',
  'function failTimedOutSubmission(uint256 bountyId, uint256 submissionId)',
  // Read
  'function bountyCount() view returns (uint256)',
  // getBounty returns Bounty memory (a struct) — must use tuple() for correct ABI decoding
  'function getBounty(uint256 bountyId) view returns (tuple(address creator, string evaluationCid, uint64 requestedClass, uint8 threshold, uint256 payoutWei, uint256 createdAt, uint64 submissionDeadline, uint8 status, address winner, uint256 submissions))',
  'function getSubmission(uint256 bountyId, uint256 submissionId) view returns (tuple(address hunter, string evaluationCid, string hunterCid, address evalWallet, bytes32 verdiktaAggId, uint8 status, uint256 acceptance, uint256 rejection, string justificationCids, uint256 submittedAt, uint256 finalizedAt, uint256 linkMaxBudget, uint256 maxOracleFee, uint256 alpha, uint256 estimatedBaseCost, uint256 maxFeeBasedScaling, string addendum))',
  'function getEffectiveBountyStatus(uint256 bountyId) view returns (string)',
  'function isAcceptingSubmissions(uint256 bountyId) view returns (bool)',
  'function verdikta() view returns (address)',
];

/**
 * Return a connected BountyEscrow Contract instance.
 * @param {string} network  - 'base' or 'base-sepolia'
 * @param {import('ethers').Signer|import('ethers').Provider} signerOrProvider
 */
export function escrowContract(network, signerOrProvider) {
  const addr = ESCROW[network];
  if (!addr) throw new Error(`No escrow address for network ${network}`);
  return new Contract(addr, BOUNTY_ESCROW_ABI, signerOrProvider);
}

/**
 * Redact an API key for safe logging (shows first 4 + last 4 chars).
 * @param {string} key
 * @returns {string}
 */
export function redactApiKey(key) {
  if (!key || key.length < 12) return '***';
  return `${key.slice(0, 4)}…${key.slice(-4)}`;
}

export function getNetwork() {
  return process.env.VERDIKTA_NETWORK || 'base';
}

export function getRpcUrl(network) {
  if (network === 'base') return process.env.BASE_RPC_URL || 'https://mainnet.base.org';
  return process.env.BASE_SEPOLIA_RPC_URL || 'https://sepolia.base.org';
}

export function resolvePath(p) {
  if (!p) return p;
  let s = String(p);
  // Expand ~ to home for convenience in .env files
  if (s.startsWith('~/')) {
    s = path.join(process.env.HOME || '', s.slice(2));
  }
  // Resolve relative paths against the scripts directory (not the caller's CWD).
  const here = path.dirname(fileURLToPath(import.meta.url));
  return path.isAbsolute(s) ? s : path.resolve(here, s);
}

export async function loadWallet() {
  const keystorePathRaw = process.env.VERDIKTA_KEYSTORE_PATH;
  const password = process.env.VERDIKTA_WALLET_PASSWORD;
  if (!keystorePathRaw || !password) {
    throw new Error(
      'Set VERDIKTA_KEYSTORE_PATH and VERDIKTA_WALLET_PASSWORD. ' +
      'To import an existing wallet, run: node wallet_init.js --import'
    );
  }
  const keystorePath = resolvePath(keystorePathRaw);
  const json = await fs.readFile(keystorePath, 'utf-8');
  return Wallet.fromEncryptedJson(json, password);
}

export function providerFor(network) {
  return new JsonRpcProvider(getRpcUrl(network));
}

export async function linkBalance(network, provider, address) {
  const linkAddr = LINK[network];
  const link = new Contract(linkAddr, ERC20_ABI, provider);
  const [bal, dec] = await Promise.all([link.balanceOf(address), link.decimals()]);
  return { bal, dec, linkAddr };
}

export function parseEth(s) {
  return parseEther(String(s));
}

// ---- CLI argument helpers ----

export function arg(name, def = null) {
  const i = process.argv.indexOf(`--${name}`);
  return i >= 0 ? process.argv[i + 1] : def;
}

export function hasFlag(name) {
  return process.argv.includes(`--${name}`);
}

export function argAll(name) {
  const vals = [];
  for (let i = 0; i < process.argv.length; i++) {
    if (process.argv[i] === `--${name}` && i + 1 < process.argv.length) {
      vals.push(process.argv[i + 1]);
    }
  }
  return vals;
}

// ---- API key loading ----

export async function loadApiKey() {
  const botFile = process.env.VERDIKTA_BOT_FILE || `${defaultSecretsDir()}/verdikta-bounties-bot.json`;
  const abs = resolvePath(botFile);
  const raw = await fs.readFile(abs, 'utf8');
  const j = JSON.parse(raw);
  return j.apiKey || j.api_key || j.bot?.apiKey || j.bot?.api_key;
}

// ---- Transaction helper ----

/**
 * Sign and broadcast a transaction, with dry-run gas estimation.
 * Exits the process on revert to prevent wasted gas.
 * @param {import('ethers').Signer} signer
 * @param {string} label - Human-readable label for logging
 * @param {object} txObj - Transaction object from API ({ to, data, value, gasLimit? })
 * @param {object} [opts]
 * @param {boolean} [opts.useApiGasLimit] - Use the gasLimit from txObj instead of estimating
 */
export async function sendTx(signer, label, txObj, { useApiGasLimit = false } = {}) {
  console.log(`\n→ ${label}: sending transaction...`);
  const baseTx = {
    to: txObj.to,
    data: txObj.data,
    value: txObj.value || '0',
  };

  let gasLimit;

  if (useApiGasLimit && txObj.gasLimit) {
    gasLimit = BigInt(txObj.gasLimit);
    console.log(`  using API-recommended gasLimit: ${gasLimit.toString()}`);
  } else {
    try {
      const estimated = await signer.estimateGas(baseTx);
      gasLimit = (estimated * 120n) / 100n;
      console.log(`  estimated gas: ${estimated.toString()} (limit: ${gasLimit.toString()})`);
    } catch (err) {
      const reason = err.reason || err.shortMessage || err.message || 'unknown';
      console.error(`\n✖ ${label} will revert! Reason: ${reason}`);
      if (err.data) console.error(`  revert data: ${err.data}`);
      process.exit(1);
    }
  }

  const tx = await signer.sendTransaction({ ...baseTx, gasLimit });
  console.log(`  tx: ${tx.hash}`);
  const receipt = await tx.wait();
  console.log(`  confirmed in block ${receipt.blockNumber}`);
  return receipt;
}

import os from 'node:os';
import path from 'node:path';
import fs from 'node:fs/promises';

export function defaultSecretsDir() {
  // Prefer XDG-ish location; keeps secrets out of the repo.
  return process.env.VERDIKTA_SECRETS_DIR || path.join(os.homedir(), '.config', 'verdikta-bounties');
}

export async function ensureDir(dir) {
  await fs.mkdir(dir, { recursive: true, mode: 0o700 });
}

#!/usr/bin/env node
import './_env.js';
import fs from 'node:fs/promises';
import path from 'node:path';
import { arg, resolvePath } from './_lib.js';
import { defaultSecretsDir, ensureDir } from './_paths.js';

const baseUrl = process.env.VERDIKTA_BOUNTIES_BASE_URL || 'https://bounties.verdikta.org';

const outPathRaw = arg('out', `${defaultSecretsDir()}/verdikta-bounties-bot.json`);
const outPath = resolvePath(outPathRaw);
const name = arg('name');
const owner = arg('owner');
const description = arg('description', 'AI agent worker for Verdikta bounties.');

if (!name || !owner) {
  console.error('Usage: node bot_register.js --name "MyBot" --owner 0x... [--description ...]');
  process.exit(1);
}

const resp = await fetch(`${baseUrl}/api/bots/register`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ name, ownerAddress: owner, description })
});

const data = await resp.json();
if (!resp.ok) {
  throw new Error(`register failed: ${resp.status} ${JSON.stringify(data)}`);
}

await ensureDir(path.dirname(outPath));
await fs.writeFile(outPath, JSON.stringify(data, null, 2), { mode: 0o600 });

console.log('Registered bot. Saved response to:', outPath);
console.log('API key (keep secret):', data?.apiKey || data?.api_key || data?.bot?.apiKey || data?.bot?.api_key || '(check file)');

#!/usr/bin/env node
import './_env.js';
// Verify setup: list open jobs + print titles.
// Confirms API connectivity. Does not submit work.

import { loadApiKey } from './_lib.js';

const baseUrl = process.env.VERDIKTA_BOUNTIES_BASE_URL || 'https://bounties.verdikta.org';

const apiKey = await loadApiKey();
if (!apiKey) throw new Error('Missing apiKey. Run onboard.js first.');

const url = new URL(`${baseUrl}/api/jobs`);
url.searchParams.set('status', 'OPEN');
url.searchParams.set('minHoursLeft', '2');

const resp = await fetch(url, {
  headers: { 'X-Bot-API-Key': apiKey }
});
const data = await resp.json();
if (!resp.ok) throw new Error(`jobs failed: ${resp.status} ${JSON.stringify(data)}`);

for (const job of (data.jobs || [])) {
  console.log(`#${job.jobId}: ${job.title} — $${job.bountyAmountUSD || 0}`);
}

#!/usr/bin/env node
// Poll for evaluation result and claim payout if the submission passed.
// The bot wallet signs the finalizeSubmission transaction automatically.
//
// Usage:
//   node claim_bounty.js --jobId 80 --submissionId 0
//   node claim_bounty.js --jobId 80 --submissionId 0 --maxWait 600
//
// Typical flow:
//   1. Run submit_to_bounty.js → submission enters PENDING_EVALUATION
//   2. Wait 2-5 minutes for oracle evaluation
//   3. Run this script → polls, then claims payout if passed
//
// Prerequisites:
//   - Submission already started (via submit_to_bounty.js)
//   - Bot wallet has ETH for gas (finalize tx)

import './_env.js';
import {
  getNetwork, providerFor, loadWallet, redactApiKey,
  arg, loadApiKey, sendTx,
} from './_lib.js';

const jobId = arg('jobId');
const submissionId = arg('submissionId');
const maxWaitSec = Number(arg('maxWait', '600')); // default 10 min

if (!jobId || submissionId == null) {
  console.error('Usage: node claim_bounty.js --jobId <ID> --submissionId <ID> [--maxWait <seconds>]');
  process.exit(1);
}

// ---- Setup ----

const network = getNetwork();
const baseUrl = (process.env.VERDIKTA_BOUNTIES_BASE_URL || '').replace(/\/+$/, '');
if (!baseUrl) {
  console.error('VERDIKTA_BOUNTIES_BASE_URL not set. Run onboard.js first.');
  process.exit(1);
}

const provider = providerFor(network);
const wallet = await loadWallet();
const signer = wallet.connect(provider);
const hunter = signer.address;

const apiKey = await loadApiKey();
if (!apiKey) {
  console.error('Missing API key. Run onboard.js first.');
  process.exit(1);
}

const headers = { 'X-Bot-API-Key': apiKey };
const jsonHeaders = { ...headers, 'Content-Type': 'application/json' };

console.log(`\nClaim bounty payout`);
console.log(`Job:          #${jobId}`);
console.log(`Submission:   #${submissionId}`);
console.log(`Network:      ${network}`);
console.log(`Hunter:       ${hunter}`);
console.log(`API:          ${baseUrl}`);
console.log(`Max wait:     ${maxWaitSec}s`);

// ---- Helper: sleep ----

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

// ---- Step 1: Poll for evaluation result ----

console.log('\n--- Step 1: Wait for evaluation result ---');

const POLL_INTERVAL_SEC = 30;
const startTime = Date.now();
let status = null;
let acceptance = null;
let rejection = null;

while (true) {
  const elapsed = Math.floor((Date.now() - startTime) / 1000);

  // Refresh submission status from blockchain
  const refreshRes = await fetch(
    `${baseUrl}/api/jobs/${jobId}/submissions/${submissionId}/refresh`,
    { method: 'POST', headers }
  );

  if (!refreshRes.ok) {
    const errData = await refreshRes.json().catch(() => ({}));
    console.error(`  Refresh failed (HTTP ${refreshRes.status}):`, JSON.stringify(errData));
    process.exit(1);
  }

  const refreshData = await refreshRes.json();
  const sub = refreshData.submission || refreshData;
  status = sub.status;
  acceptance = sub.acceptance;
  rejection = sub.rejection;

  console.log(`  [${elapsed}s] Status: ${status}  (acceptance: ${acceptance ?? '?'}, rejection: ${rejection ?? '?'})`);

  // Terminal states — evaluation is done
  if (status === 'ACCEPTED_PENDING_CLAIM') {
    console.log(`\n  ✓ Evaluation passed! Score: ${acceptance}%`);
    break;
  }
  if (status === 'REJECTED_PENDING_FINALIZATION') {
    console.log(`\n  ✗ Evaluation failed. Score: ${acceptance}% (threshold not met)`);
    console.log(`  The submission did not pass. No payout to claim.`);
    // Still finalize to pull results on-chain (releases LINK back)
    break;
  }
  if (status === 'APPROVED' || status === 'REJECTED') {
    console.log(`\n  Already finalized (status: ${status}).`);
    if (sub.paidWinner) {
      console.log('  Payout already claimed.');
    }
    process.exit(0);
  }

  // Check timeout
  if (elapsed >= maxWaitSec) {
    console.error(`\n  Timed out after ${maxWaitSec}s. Status still: ${status}`);
    console.error(`  Re-run this script later to check again.`);
    process.exit(1);
  }

  // Wait before next poll
  const remaining = maxWaitSec - elapsed;
  const waitSec = Math.min(POLL_INTERVAL_SEC, remaining);
  console.log(`  Waiting ${waitSec}s before next check...`);
  await sleep(waitSec * 1000);
}

// ---- Step 2: Finalize submission (claim payout) ----

console.log('\n--- Step 2: Finalize submission (claim payout) ---');

const finalizeRes = await fetch(
  `${baseUrl}/api/jobs/${jobId}/submissions/${submissionId}/finalize`,
  {
    method: 'POST',
    headers: jsonHeaders,
    body: JSON.stringify({ hunter }),
  }
);
const finalizeData = await finalizeRes.json();

if (!finalizeRes.ok || !finalizeData.transaction) {
  if (finalizeData.error === 'Evaluation not ready') {
    console.error('  Evaluation not ready yet. Wait a bit longer and re-run.');
  } else {
    console.error('  Finalize failed:', JSON.stringify(finalizeData, null, 2));
  }
  // Try /diagnose for more context
  try {
    const diagRes = await fetch(
      `${baseUrl}/api/jobs/${jobId}/submissions/${submissionId}/diagnose`,
      { headers }
    );
    if (diagRes.ok) {
      const diag = await diagRes.json();
      if (diag.issues?.length) {
        console.error('\n  Diagnosis:');
        diag.issues.forEach(i => console.error(`    - [${i.severity || 'info'}] ${i.message || i}`));
      }
      if (diag.recommendations?.length) {
        console.error('  Recommendations:');
        diag.recommendations.forEach(r => console.error(`    → ${r}`));
      }
    }
  } catch { /* best-effort */ }
  process.exit(1);
}

if (finalizeData.oracleResult) {
  const or = finalizeData.oracleResult;
  console.log(`  Oracle result: acceptance=${or.acceptance}%, rejection=${or.rejection}%, passed=${or.passed}`);
}
if (finalizeData.expectedPayout) {
  console.log(`  Expected payout: ${finalizeData.expectedPayout} ETH`);
}

const finalizeReceipt = await sendTx(signer, 'finalizeSubmission', finalizeData.transaction);

// ---- Done ----

const passed = status === 'ACCEPTED_PENDING_CLAIM';

console.log(`\n✅ Finalization complete!`);
console.log(`   Job:          #${jobId}`);
console.log(`   Submission:   #${submissionId}`);
console.log(`   Score:        ${acceptance}%`);
console.log(`   Result:       ${passed ? 'PASSED — payout claimed!' : 'FAILED — LINK refunded'}`);
if (passed && finalizeData.expectedPayout) {
  console.log(`   Payout:       ${finalizeData.expectedPayout} ETH → ${hunter}`);
}
const safeKey = redactApiKey(apiKey);
console.log(`\nTo see detailed evaluation feedback:`);
console.log(`  curl -H "X-Bot-API-Key: ${safeKey}" ${baseUrl}/api/jobs/${jobId}/submissions/${submissionId}/evaluation`);

#!/usr/bin/env node
// Complete bounty creation: API (build evaluation package) → on-chain (fund bounty).
// The bot wallet signs the on-chain transaction automatically.
//
// Usage:
//   node create_bounty.js --config bounty.json
//
// bounty.json example:
// {
//   "title": "Book Review: The Pragmatic Programmer",
//   "description": "Write a 500-word review...",
//   "bountyAmount": "0.001",
//   "threshold": 75,
//   "classId": 128,
//   "submissionWindowHours": 24,
//   "workProductType": "writing",
//   "rubricJson": {
//     "title": "Book Review",
//     "criteria": [
//       { "id": "quality", "label": "Quality", "description": "...", "weight": 0.5, "must": false },
//       { "id": "clarity", "label": "Clarity", "description": "...", "weight": 0.5, "must": true }
//     ],
//     "threshold": 75,
//     "forbiddenContent": []
//   },
//   "juryNodes": [
//     { "provider": "OpenAI", "model": "gpt-5.2-2025-12-11", "weight": 0.5, "runs": 1 },
//     { "provider": "Anthropic", "model": "claude-3-5-haiku-20241022", "weight": 0.5, "runs": 1 }
//   ]
// }
//
// Prerequisites:
//   - Bot onboarded (onboard.js completed)
//   - Bot wallet funded with ETH
//   - Bot registered (API key saved)

import './_env.js';
import fs from 'node:fs/promises';
import { ethers } from 'ethers';
import {
  getNetwork, providerFor, loadWallet,
  ESCROW, escrowContract, arg, loadApiKey,
} from './_lib.js';

const configPath = arg('config');
if (!configPath) {
  console.error('Usage: node create_bounty.js --config bounty.json');
  console.error('See script header for bounty.json format.');
  process.exit(1);
}

// ---- Load config ----

let config;
try {
  const raw = await fs.readFile(configPath, 'utf8');
  config = JSON.parse(raw);
} catch (e) {
  console.error(`Failed to read config file: ${e.message}`);
  process.exit(1);
}

const {
  title,
  description,
  bountyAmount,
  bountyAmountUSD,
  threshold = 75,
  classId = 128,
  submissionWindowHours = 24,
  workProductType = 'writing',
  rubricJson,
  juryNodes,
} = config;

// Validate required fields
if (!title || !description) {
  console.error('Config must include "title" and "description".');
  process.exit(1);
}
if (!bountyAmount || isNaN(Number(bountyAmount)) || Number(bountyAmount) <= 0) {
  console.error('Config must include a positive "bountyAmount" (ETH).');
  process.exit(1);
}
if (!rubricJson || !Array.isArray(rubricJson.criteria) || rubricJson.criteria.length === 0) {
  console.error('Config must include "rubricJson" with at least one criterion.');
  process.exit(1);
}

// Validate each criterion has all required fields
const criterionErrors = [];
const seenIds = new Set();
for (let i = 0; i < rubricJson.criteria.length; i++) {
  const c = rubricJson.criteria[i];
  if (!c.id || typeof c.id !== 'string') criterionErrors.push(`Criterion ${i}: missing or invalid "id" (string)`);
  if (seenIds.has(c.id)) criterionErrors.push(`Criterion ${i}: duplicate id "${c.id}"`);
  seenIds.add(c.id);
  if (!c.description || typeof c.description !== 'string') criterionErrors.push(`Criterion ${i}: missing "description" (string)`);
  if (typeof c.weight !== 'number' || c.weight < 0 || c.weight > 1) criterionErrors.push(`Criterion ${i}: missing or invalid "weight" (number 0-1)`);
  if (typeof c.must !== 'boolean') criterionErrors.push(`Criterion ${i}: missing "must" field (boolean, required). Set true for must-pass, false for weighted.`);
}
if (criterionErrors.length > 0) {
  console.error('Rubric criteria validation failed:');
  criterionErrors.forEach(e => console.error(`  - ${e}`));
  process.exit(1);
}

// Validate criteria weights sum to ~1.0
const criteriaWeightSum = rubricJson.criteria.reduce((s, c) => s + (c.weight || 0), 0);
if (Math.abs(criteriaWeightSum - 1.0) > 0.01) {
  console.error(`Criteria weights must sum to 1.0 (got ${criteriaWeightSum.toFixed(4)}).`);
  process.exit(1);
}

if (!juryNodes || !Array.isArray(juryNodes) || juryNodes.length === 0) {
  console.error('Config must include "juryNodes" array with at least one model.');
  process.exit(1);
}

// Validate jury weights sum to ~1.0
const weightSum = juryNodes.reduce((s, n) => s + (n.weight || 0), 0);
if (Math.abs(weightSum - 1.0) > 0.01) {
  console.error(`Jury node weights must sum to 1.0 (got ${weightSum.toFixed(4)}).`);
  process.exit(1);
}

// ---- Setup ----

const network = getNetwork();
const baseUrl = (process.env.VERDIKTA_BOUNTIES_BASE_URL || '').replace(/\/+$/, '');
if (!baseUrl) {
  console.error('VERDIKTA_BOUNTIES_BASE_URL not set. Run onboard.js first.');
  process.exit(1);
}

const provider = providerFor(network);
const wallet = await loadWallet();
const signer = wallet.connect(provider);
const creator = signer.address;

const apiKey = await loadApiKey();
if (!apiKey) {
  console.error('Missing API key. Run onboard.js first.');
  process.exit(1);
}

console.log(`\nCreating bounty: ${title}`);
console.log(`Network:  ${network}`);
console.log(`Creator:  ${creator}`);
console.log(`Amount:   ${bountyAmount} ETH`);
console.log(`Threshold: ${threshold}%`);
console.log(`Class:    ${classId}`);
console.log(`Window:   ${submissionWindowHours}h`);
console.log(`Jury:     ${juryNodes.map(n => `${n.provider}/${n.model}`).join(', ')}`);
console.log(`API:      ${baseUrl}`);

// ---- Step 1: Create job via API ----

console.log('\n--- Step 1: Create job via API (builds evaluation package + pins to IPFS) ---');

const apiBody = {
  title,
  description,
  creator,
  bountyAmount: String(bountyAmount),
  bountyAmountUSD: bountyAmountUSD || 0,
  threshold: Number(threshold),
  classId: Number(classId),
  submissionWindowHours: Number(submissionWindowHours),
  workProductType,
  rubricJson,
  juryNodes,
};

const apiRes = await fetch(`${baseUrl}/api/jobs/create`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'X-Bot-API-Key': apiKey,
  },
  body: JSON.stringify(apiBody),
});

const apiData = await apiRes.json();
if (!apiRes.ok || !apiData.success) {
  console.error('API create failed:', JSON.stringify(apiData, null, 2));
  process.exit(1);
}

const jobId = apiData.job?.jobId;
// API may return the CID as primaryCid or evaluationCid depending on version
const primaryCid = apiData.job?.primaryCid || apiData.job?.evaluationCid;

if (!primaryCid) {
  console.error('API response missing primaryCid/evaluationCid:', JSON.stringify(apiData));
  process.exit(1);
}

console.log(`  Initial API Job ID: ${jobId}`);
console.log(`  evaluationCid: ${primaryCid}`);

// ---- Step 2: Create bounty on-chain ----

console.log('\n--- Step 2: Create bounty on-chain (bot wallet signs tx) ---');

const contractAddress = ESCROW[network];
if (!contractAddress) {
  console.error(`No escrow address for network ${network}`);
  process.exit(1);
}

const contract = escrowContract(network, signer);
const deadline = Math.floor(Date.now() / 1000) + (Number(submissionWindowHours) * 3600);
const value = ethers.parseEther(String(bountyAmount));

console.log(`  Escrow:    ${contractAddress}`);
console.log(`  CID:       ${primaryCid}`);
console.log(`  Deadline:  ${new Date(deadline * 1000).toISOString()}`);

// Dry-run first to catch revert reasons before spending gas
try {
  const gas = await contract.createBounty.estimateGas(primaryCid, classId, threshold, deadline, { value });
  console.log(`  estimated gas: ${gas.toString()}`);
} catch (err) {
  const reason = err.reason || err.shortMessage || err.message || 'unknown';
  console.error(`\n✖ createBounty will revert! Reason: ${reason}`);
  if (err.data) console.error(`  revert data: ${err.data}`);
  process.exit(1);
}

const tx = await contract.createBounty(primaryCid, classId, threshold, deadline, { value });
console.log(`  tx: ${tx.hash}`);
const receipt = await tx.wait();

let bountyId = null;
for (const log of (receipt.logs || [])) {
  try {
    const parsed = contract.interface.parseLog(log);
    if (parsed?.name === 'BountyCreated') {
      bountyId = String(parsed.args.bountyId ?? parsed.args[0]);
      break;
    }
  } catch {}
}

console.log(`  Confirmed in block: ${receipt.blockNumber}`);
console.log(`  On-chain bountyId:  ${bountyId ?? '(not parsed)'}`);

// ---- Step 3: Link on-chain bounty to API job ----
//
// The API sync service may reconcile the jobId to match the on-chain bountyId
// before our link call runs. When that happens, the job moves from apiJobId (e.g. 19)
// to bountyId (e.g. 12) in the API. We handle this by checking both IDs.

console.log('\n--- Step 3: Link on-chain bounty ID to API job ---');

// effectiveJobId is the ID to use for all subsequent API calls.
// Starts as the original apiJobId, but may change to bountyId after reconciliation.
let effectiveJobId = jobId;
let linked = false;

if (bountyId != null) {
  // Attempt 1: Direct link via original apiJobId
  const linkRes = await fetch(`${baseUrl}/api/jobs/${jobId}/bountyId`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      'X-Bot-API-Key': apiKey,
    },
    body: JSON.stringify({
      bountyId: Number(bountyId),
      txHash: tx.hash,
      blockNumber: receipt.blockNumber,
    }),
  });

  if (linkRes.ok) {
    const linkData = await linkRes.json();
    const reconciledId = linkData.job?.jobId ?? bountyId;
    effectiveJobId = reconciledId;
    linked = true;
    console.log(`  Linked: API job ${jobId} → on-chain bounty ${reconciledId}`);
    if (Number(reconciledId) !== Number(jobId)) {
      console.log(`  Note: API reconciled jobId from ${jobId} → ${reconciledId} (aligned with on-chain)`);
    }
  } else {
    console.warn(`  Direct link failed (HTTP ${linkRes.status}) — job ${jobId} may have been reconciled by sync service.`);

    // Attempt 2: Check if sync service already reconciled the job under the bountyId
    console.log(`  Waiting 3s for sync service, then checking API job at bountyId ${bountyId}...`);
    await new Promise(r => setTimeout(r, 3000));

    const syncCheckRes = await fetch(`${baseUrl}/api/jobs/${bountyId}`, {
      headers: { 'X-Bot-API-Key': apiKey },
    });

    if (syncCheckRes.ok) {
      const syncCheckData = await syncCheckRes.json();
      const syncJob = syncCheckData.job || syncCheckData;
      const syncCid = syncJob.primaryCid || syncJob.evaluationCid;

      if (syncCid === primaryCid) {
        // Sync service reconciled correctly — job now lives at bountyId
        effectiveJobId = Number(bountyId);
        linked = true;
        console.log(`  ✓ Sync service already reconciled: job now at ID ${bountyId} with matching CID.`);
      } else if (syncCid) {
        console.warn(`  Found job at bountyId ${bountyId} but CID doesn't match:`);
        console.warn(`    API CID:      ${syncCid}`);
        console.warn(`    Expected CID: ${primaryCid}`);
        console.warn(`  This may be a different bounty occupying ID ${bountyId}.`);
      }
    }

    if (!linked) {
      // Attempt 3: Try resolve endpoint using bountyId (in case job moved)
      console.warn(`  Trying resolve via bountyId ${bountyId}...`);
      const resolveRes = await fetch(`${baseUrl}/api/jobs/${bountyId}/bountyId/resolve`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'X-Bot-API-Key': apiKey,
        },
        body: JSON.stringify({
          creator,
          rubricCid: primaryCid,
          submissionCloseTime: deadline,
          txHash: tx.hash,
        }),
      });

      if (resolveRes.ok) {
        const resolveData = await resolveRes.json();
        effectiveJobId = resolveData.bountyId ?? bountyId;
        linked = true;
        console.log(`  Linked via resolve (method: ${resolveData.method}, bountyId: ${resolveData.bountyId})`);
      } else {
        // Attempt 4: Also try resolve with the original apiJobId
        const resolveRes2 = await fetch(`${baseUrl}/api/jobs/${jobId}/bountyId/resolve`, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'X-Bot-API-Key': apiKey,
          },
          body: JSON.stringify({
            creator,
            rubricCid: primaryCid,
            submissionCloseTime: deadline,
            txHash: tx.hash,
          }),
        });

        if (resolveRes2.ok) {
          const resolveData2 = await resolveRes2.json();
          effectiveJobId = resolveData2.bountyId ?? bountyId;
          linked = true;
          console.log(`  Linked via resolve on apiJobId (method: ${resolveData2.method}, bountyId: ${resolveData2.bountyId})`);
        } else {
          console.warn(`  ⚠ All link attempts failed. The bounty exists on-chain (bountyId=${bountyId})`);
          console.warn(`    but the API could not be linked.`);
          console.warn(`    The sync service may resolve this automatically. Use bountyId ${bountyId} for API calls.`);
          // Default to bountyId since that's the on-chain truth
          effectiveJobId = Number(bountyId);
        }
      }
    }
  }
} else {
  console.warn('  ⚠ Could not parse bountyId from event — skipping link step.');
  console.warn(`    Wait for auto-sync or manually call: PATCH /api/jobs/${jobId}/bountyId/resolve`);
}

console.log(`\n  Effective job ID for API calls: ${effectiveJobId}`);

// ---- Step 4: Verify on-chain integrity ----

console.log('\n--- Step 4: Verify on-chain ↔ API integrity ---');

let integrityOk = true;
const issues = [];

if (bountyId != null) {
  try {
    // On-chain verification via getBounty
    // Retry with backoff to handle RPC eventual consistency on public endpoints
    // (load-balanced RPCs may serve stale state right after tx.wait())
    const readContract = escrowContract(network, provider);
    let onChain;
    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        onChain = await readContract.getBounty(BigInt(bountyId));
        break;
      } catch (rpcErr) {
        if (attempt < 3 && rpcErr.message?.includes('bad bountyId')) {
          console.log(`  (RPC returned stale state for bountyId ${bountyId}, retrying in ${attempt * 2}s...)`);
          await new Promise(r => setTimeout(r, attempt * 2000));
        } else {
          throw rpcErr;
        }
      }
    }
    // onChain is a tuple: { creator, evaluationCid, requestedClass, threshold, payoutWei, createdAt, submissionDeadline, status, winner, submissions }

    const chainCreator = onChain.creator ?? onChain[0];
    const chainCid = onChain.evaluationCid ?? onChain[1];
    const chainClass = Number(onChain.requestedClass ?? onChain[2]);
    const chainThreshold = Number(onChain.threshold ?? onChain[3]);

    if (chainCreator.toLowerCase() !== creator.toLowerCase()) {
      issues.push(`creator mismatch: on-chain=${chainCreator}, expected=${creator}`);
    }
    if (chainCid !== primaryCid) {
      issues.push(`evaluationCid mismatch: on-chain=${chainCid}, expected=${primaryCid}`);
    }
    if (chainClass !== Number(classId)) {
      issues.push(`classId mismatch: on-chain=${chainClass}, expected=${classId}`);
    }
    if (chainThreshold !== Number(threshold)) {
      issues.push(`threshold mismatch: on-chain=${chainThreshold}, expected=${threshold}`);
    }

    if (issues.length === 0) {
      console.log('  On-chain: creator, CID, classId, threshold all match. ✓');
    }
  } catch (err) {
    issues.push(`on-chain getBounty failed: ${err.message}`);
  }

  // API cross-check (use effectiveJobId, which may be bountyId after reconciliation)
  try {
    const verifyRes = await fetch(`${baseUrl}/api/jobs/${effectiveJobId}`, {
      headers: { 'X-Bot-API-Key': apiKey },
    });
    if (verifyRes.ok) {
      const verifyData = await verifyRes.json();
      const apiJob = verifyData.job || verifyData;
      const apiCid = apiJob.primaryCid || apiJob.evaluationCid;
      if (apiCid && apiCid !== primaryCid) {
        issues.push(`API CID mismatch: API=${apiCid}, expected=${primaryCid}`);
      }
      if (issues.length === 0) {
        console.log(`  API cross-check (jobId=${effectiveJobId}): evaluationCid match. ✓`);
      }
    } else {
      issues.push(`API job fetch failed: GET /api/jobs/${effectiveJobId} returned HTTP ${verifyRes.status}`);
    }
  } catch (err) {
    issues.push(`API cross-check failed: ${err.message}`);
  }

  if (issues.length > 0) {
    integrityOk = false;
    console.warn('\n  ⚠ INTEGRITY ISSUES DETECTED:');
    issues.forEach(i => console.warn(`    - ${i}`));
    console.warn('  DO NOT submit to this bounty until issues are resolved.');
    console.warn('  This may indicate API index drift or ID collision on mainnet.');
  }
} else {
  console.warn('  Skipping integrity check (bountyId not parsed from event).');
  integrityOk = false;
}

// ---- Done ----

const verdict = integrityOk ? 'GO' : 'NO-GO (see warnings above)';
console.log(`\n✅ Bounty created successfully!  Integrity: ${verdict}`);
console.log(`   Title:        ${title}`);
console.log(`   API Job ID:   ${jobId} (original)`);
console.log(`   Effective ID: ${effectiveJobId} (use this for API calls)`);
console.log(`   Bounty ID:    ${bountyId} (on-chain)`);
console.log(`   Amount:       ${bountyAmount} ETH`);
console.log(`   Deadline:     ${new Date(deadline * 1000).toISOString()}`);
console.log(`   Linked:       ${linked ? 'yes' : 'no (sync service may resolve automatically)'}`);
console.log(`\n   View: ${baseUrl.replace('/api', '')}`);

// Machine-parseable identifiers for automation harnesses
console.log(`API_JOB_ID=${jobId}`);
console.log(`EFFECTIVE_JOB_ID=${effectiveJobId}`);
console.log(`CANONICAL_JOB_ID=${effectiveJobId}`);
console.log(`BOUNTY_ID=${bountyId}`);

#!/usr/bin/env node
import './_env.js';
import { ethers } from 'ethers';
import { getNetwork, providerFor, loadWallet, parseEth, arg, loadApiKey, ESCROW } from './_lib.js';

// Minimal on-chain bounty creation (no IPFS upload).
// Intended for testnet smoke tests only.
//
// IMPORTANT: This uses a hardcoded evaluation CID by default, which produces
// a bounty without a real evaluation package (no title, rubric, or jury config
// in the UI). For a full end-to-end test with a properly evaluable bounty,
// create via the web UI or the HTTP API (POST /api/jobs/create) instead.

const network = getNetwork();
const provider = providerFor(network);
const wallet = await loadWallet();
const signer = wallet.connect(provider);

const contractAddress = ESCROW[network];
if (!contractAddress) throw new Error(`Missing escrow address for network=${network}`);

const evaluationCid = arg('cid', 'QmRLB6LYe6VER6UQDoX7wt4LmKATHbGA81ny5vgRMbfrtX');
// NOTE: This script does on-chain creation only. If you want a titled job + full evaluation package,
// create via the HTTP API first (POST /api/jobs/create), then create on-chain with job.primaryCid.
const classId = Number(arg('classId', '128')); // default active class (Core)

// ---- Preflight: verify class exists + is ACTIVE and has models (via Agent API) ----

async function preflightClassOrThrow(classId) {
  const noPreflight = process.argv.includes('--no-preflight');
  if (noPreflight) return;

  const baseUrl = (process.env.VERDIKTA_BOUNTIES_BASE_URL || '').replace(/\/+$/, '');
  if (!baseUrl) {
    console.warn('[preflight] VERDIKTA_BOUNTIES_BASE_URL not set; skipping class preflight. (use --no-preflight to silence)');
    return;
  }

  let apiKey = null;
  try {
    apiKey = await loadApiKey();
  } catch (e) {
    console.warn(`[preflight] Could not load bot API key; skipping class preflight: ${e.message}`);
    return;
  }
  if (!apiKey) {
    console.warn('[preflight] Bot file missing apiKey; skipping class preflight.');
    return;
  }

  const headers = { 'X-Bot-API-Key': apiKey };

  const clsRes = await fetch(`${baseUrl}/api/classes/${classId}`, { headers });
  if (!clsRes.ok) {
    const t = await clsRes.text().catch(() => '');
    throw new Error(`[preflight] Class ${classId} not available on ${baseUrl} (HTTP ${clsRes.status}). ${t}`);
  }
  const clsJson = await clsRes.json();
  const status = clsJson?.class?.status;
  if (status !== 'ACTIVE') {
    throw new Error(`[preflight] Class ${classId} is not ACTIVE (status=${status}). Pick an ACTIVE class from GET /api/classes?status=ACTIVE`);
  }

  const modelsRes = await fetch(`${baseUrl}/api/classes/${classId}/models`, { headers });
  if (!modelsRes.ok) {
    const t = await modelsRes.text().catch(() => '');
    throw new Error(`[preflight] Failed to fetch models for class ${classId} (HTTP ${modelsRes.status}). ${t}`);
  }
  const modelsJson = await modelsRes.json();
  const modelCount = Array.isArray(modelsJson?.models) ? modelsJson.models.length : 0;
  if (modelCount === 0) {
    throw new Error(`[preflight] Class ${classId} returned 0 models. Refusing to create bounty (would likely be unevaluable).`);
  }

  console.log(`[preflight] ✅ class ${classId} ACTIVE; models available: ${modelCount}`);
}
const threshold = Number(arg('threshold', '80'));
const hours = Number(arg('hours', '6'));
const amountEth = arg('eth', '0.001');

const deadline = Math.floor(Date.now() / 1000) + Math.floor(hours * 3600);
const value = parseEth(amountEth);

const ABI = [
  'function createBounty(string evaluationCid, uint64 requestedClass, uint8 threshold, uint64 submissionDeadline) payable returns (uint256)',
  'event BountyCreated(uint256 indexed bountyId, address indexed creator, string evaluationCid, uint64 classId, uint8 threshold, uint256 payoutWei, uint64 submissionDeadline)'
];

const contract = new ethers.Contract(contractAddress, ABI, signer);

await preflightClassOrThrow(classId);

console.log('Creating bounty on-chain');
console.log('Network:', network);
console.log('Escrow:', contractAddress);
console.log('Creator:', signer.address);
console.log('CID:', evaluationCid);
console.log('classId:', classId);
console.log('threshold:', threshold);
console.log('deadline:', deadline, `(in ${hours}h)`);
console.log('value:', amountEth, 'ETH');

const tx = await contract.createBounty(evaluationCid, classId, threshold, deadline, { value });
console.log('Tx:', tx.hash);
const receipt = await tx.wait();

let bountyId = null;
for (const log of (receipt.logs || [])) {
  try {
    const parsed = contract.interface.parseLog(log);
    if (parsed?.name === 'BountyCreated') {
      bountyId = String(parsed.args.bountyId ?? parsed.args[0]);
      break;
    }
  } catch {}
}

console.log('Confirmed in block:', receipt.blockNumber);
console.log('BountyId:', bountyId ?? '(not parsed)');

